// Junta reativacao + vip_em_risco, remove duplicados, remove quem já tem
// mensagem pendente por aprovar, e limita o volume diário (protege a Bea
// de uma avalancha de aprovações e a quota do Groq).
const LIMITE_DIARIO = 15;

const reativacao = ($('Buscar Clientes em Reativação').first()?.json?.data) || [];
const vipRisco = ($('Buscar Clientes VIP em Risco').first()?.json?.data) || [];
const pendentes = ($('Buscar Mensagens Pendentes').first()?.json?.data) || [];

const idsComPendente = new Set(pendentes.map(m => m.clienteId));

const vistos = new Set();
const candidatos = [];
for (const c of [...reativacao, ...vipRisco]) {
  if (vistos.has(c.id)) continue;
  if (idsComPendente.has(c.id)) continue;
  vistos.add(c.id);
  candidatos.push({ json: c });
}

return candidatos.slice(0, LIMITE_DIARIO);

const p = $json.data;
const agora = Date.now();

const diasSemSessao = p.ultimaSessao
  ? Math.floor((agora - new Date(p.ultimaSessao).getTime()) / 86400000)
  : null;

const contagem = {};
for (const s of (p.sessoes || [])) {
  if (s.estado !== 'realizada' || !s.servico) continue;
  contagem[s.servico] = (contagem[s.servico] || 0) + 1;
}
const servicoFrequente = Object.entries(contagem).sort((a, b) => b[1] - a[1])[0]?.[0] || null;

const primeiroNome = (p.nome || '').split(' ')[0] || 'lá';
const cortar = (txt, n) => !txt ? null : (txt.length > n ? txt.slice(0, n) + '...' : txt);

const EXEMPLOS_REAIS_BEA = [
  '"Estou beem tambem querida 😊 Temos de combinar alguma coisa. Ja não nos vemos desde o inicio do ano"',
  '"Bom dia 😊 pretende agendar ?"',
  '"Amanhã, sem problema algum 😉"',
  '"Que ótima ideia! Nada a agradecer, vocês são muito amáveis. Acreditamos mesmo que pequenos detalhes fazem toda a diferença numa experiência. Um beijinho MUITO grande e até breve! 🤍"',
  '"Olá Patrícia\nComo estão? Espero que esteja tudo bem consigo e com o seu marido 😊\nLembramo-nos de vocês por estes dias, daquele momento que tiraram para vocês aqui connosco 🤍\nSe fizer sentido para si, diga-me e tento ajudar.\nUm beijinho" (este é mais longo por ser campanha — NORMALMENTE escreve mais curto, como os de cima)',
].join('\n\n');

const FECHOS_POSSIVEIS = [
  'Diga-me como tem estado',
  'Conte-me novidades',
  'Como tem passado?',
  'Um beijinho, até breve',
  'Fico a pensar em si',
  'Um grande beijinho, até já',
];
const fechoAtribuido = FECHOS_POSSIVEIS[$itemIndex % FECHOS_POSSIVEIS.length];

const ABERTURAS_POSSIVEIS = [
  'Começa com uma saudação direta e simples, tipo "Olá ' + primeiroNome + ' 😊" seguida LOGO do facto em si, sem anunciar que é uma memória — vai direta ao assunto como quem continua uma conversa',
  'Começa por uma pergunta genuína e calorosa sobre o BEM-ESTAR dela relacionada com o facto (nunca sobre marcações, nunca oferecendo ajuda prática ou logística) — ex: "Como tem estado com...?" ou "Isso ainda a tem ocupado?"',
  'Começa pelo nome dela e uma observação direta sobre o facto, sem usar a palavra "lembro" nem "lembrei" em lado nenhum da frase — ex: "' + primeiroNome + ', esse tempo todo de..."',
  'Podes usar "lembro-me"/"lembrei-me" mas NUNCA como as primeiras palavras da mensagem — insere a meio da frase, depois de uma saudação ou de outra ideia',
  'Usa uma expressão de memória DIFERENTE de "lembro-me"/"lembrei-me": por exemplo "não consegui deixar de pensar em", "ainda hoje me veio à cabeça", "tenho pensado em si por causa de", "não parei de pensar em"',
  'Começa diretamente pelo facto descrito como continuação natural, sem qualquer verbo de memória (nem "lembro", nem "pensei", nem similares) — só descreve o facto como algo presente, tipo "Essas noites intensas de trabalho..."',
].join('|||');
const listaAberturas = ABERTURAS_POSSIVEIS.split('|||');
const aberturaAtribuida = listaAberturas[($itemIndex + 2) % listaAberturas.length];

const REGRAS = [
  'REGRAS ABSOLUTAS — baseadas em como a Bea escreve DE VERDADE no WhatsApp (exemplos reais acima), não num manual de marca abstrato',
  '- CURTA. 1 a 2 frases curtas no corpo (sem contar saudação e fecho)',
  '- Português europeu, tratamento por VOCÊ — NUNCA tratar por tu',
  '- SEMPRE 2ª pessoa ao falar da cliente ("a sua", "consigo", "lembro-me de si") — NUNCA 3ª pessoa ("dela", "ela mencionou")',
  '- IMPORTANTE: usa o nome exatamente como fornecido — NUNCA inventes outro nome',
  '- A REGRA MAIS IMPORTANTE DE TODAS, NUNCA QUEBRAR: esta mensagem é PURAMENTE emocional, nunca prática. Não perguntes, sugiras, proponhas, ofereças ajuda, nem insinues marcar/agendar/combinar/confirmar/resolver NADA — nem de forma direta nem disfarçada de simpatia. Não tentes resolver questões práticas que a cliente tenha levantado no passado — só reconhece o lado emocional/humano do facto, nunca a parte logística. A mensagem tem de conseguir ser lida em voz alta sem soar a atendimento ao cliente — soa a uma amiga a pensar em ti, ponto final, sem propor nada, sem oferecer nada, sem perguntar sobre planos',
  '- NUNCA mencionar packs, sessões restantes, preços ou descontos — mesmo que existam nos dados, são só contexto interno',
  '- Se houver mensagens anteriores já enviadas listadas abaixo, NUNCA repitas o mesmo ângulo/facto que já foi usado nelas — escolhe algo novo',
  '- PROIBIDO mencionar o número de dias/semanas/meses desde a última visita',
  '- PROIBIDO tom de relatório clínico',
  '- PROIBIDO usar travessão no meio de frases na MENSAGEM FINAL -- usa vírgula, dois pontos ou ponto final',
  '- PROIBIDO começar SEMPRE por "Lembro-me"/"Lembrei-me" — já se tornou repetitivo e não é como a Bea escreve de verdade',
  `- ESTILO DE ABERTURA OBRIGATÓRIO PARA ESTA MENSAGEM: ${aberturaAtribuida}`,
  '- ESCOLHA DO SINAL: prioriza (1) mudança de comportamento/situação emocionalmente forte > (2) facto de vida específico e pessoal > (3) feedback/comentário real que a cliente deixou > (4) preferência de serviço neutra',
  '- O OBJETIVO É A CLIENTE SENTIR-SE Única — sé tão específica que a mensagem só podia ser sobre ela',
  `- FECHO OBRIGATÓRIO: a mensagem tem de terminar exatamente com esta frase: "${fechoAtribuido}" — nada depois disso`,
  '- Emojis à vontade no estilo dela (🌿😊😉🤍🧭), no máximo 1-2',
  '- A cliente é mulher: formas femininas',
  '- Nunca mencionar IA/sistema automático, urgência artificial, clichés de wellness',
].join('\n');

const systemPrompt = `És a pessoa responsável por escrever mensagens de WhatsApp da Essence Wellness, um centro de massagens de relaxamento em Vila Nova de Gaia. Escreves para reabrir contacto com uma cliente que não vem há algum tempo, IMITANDO O ESTILO REAL da Bea (dona do espaço) nestes exemplos genuínos dela:\n\n${EXEMPLOS_REAIS_BEA}\n\n${REGRAS}\n\nFORMATO DE SAÍDA\nDevolve APENAS um objeto JSON válido, sem markdown e sem blocos de código:\n{"mensagem": "...", "motivo": "resumo curto do ângulo escolhido, para a Bea perceber porque a IA escreveu isto"}`;

// Resumo compacto do perfil — só os 2-3 sinais mais fortes de cada fonte,
// truncados, para não disparar tokens de entrada com dados irrelevantes
const observacoesLinhas = (p.observacoes || [])
  .slice(0, 3)
  .map(o => o.texto)
  .filter(Boolean)
  .map(t => `- ${cortar(t, 200)}`);

const etiquetasNomes = (p.etiquetas || []).map(e => e.etiqueta?.nome).filter(Boolean);
const etiquetasLinha = etiquetasNomes.length ? `- Etiquetas: ${etiquetasNomes.slice(0, 5).join(', ')}` : null;

const tarefasAbertas = (p.tarefas || [])
  .filter(t => t.estado !== 'concluida' && t.estado !== 'cancelada')
  .slice(0, 2)
  .map(t => `- Follow-up em aberto: ${cortar(t.titulo, 100)}`);

const mensagensAnteriores = (p.mensagens || [])
  .filter(m => m.estado === 'enviada')
  .slice(0, 2)
  .map(m => `- Já recebeu esta mensagem antes (NÃO REPETIR O ÂNGULO): "${cortar(m.mensagemFinal || m.mensagemGerada, 150)}"`);

const feedbacksLinhas = (p.feedbacks || [])
  .slice(0, 2)
  .map(f => {
    const partes = [
      f.npsScore != null ? `NPS ${f.npsScore}/10` : null,
      f.motivoRegresso ? `motivo p/ voltar: "${cortar(f.motivoRegresso, 120)}"` : null,
      f.momentoPico ? `momento alto: ${f.momentoPico}` : null,
      f.comentario ? `comentário: "${cortar(f.comentario, 150)}"` : null,
    ].filter(Boolean).join(' | ');
    return partes ? `- Feedback real de sessão: ${partes}` : null;
  })
  .filter(Boolean);

const packsLinha = (p.packs && p.packs.length)
  ? `- (uso interno, NUNCA mencionar) Tem pack ativo: ${p.packs[0].servico?.nome || ''}`
  : null;

const sinaisLinhas = [
  p.fichaClinica ? `- Ficha clínica/contexto pessoal: ${cortar(p.fichaClinica, 300)}` : null,
  ...observacoesLinhas,
  etiquetasLinha,
  ...feedbacksLinhas,
  ...tarefasAbertas,
  ...mensagensAnteriores,
  servicoFrequente ? `- (preferência neutra, só usar se nada acima servir) Serviço que mais costuma marcar: ${servicoFrequente}` : null,
  packsLinha,
].filter(Boolean).join('\n');

const userPrompt = [
  `Nome da cliente (usa exatamente este nome): ${primeiroNome}`,
  '',
  'SINAIS REAIS SOBRE ESTA CLIENTE:',
  sinaisLinhas || '- (sem sinais específicos disponíveis — usa um tom genérico mas caloroso)',
  '',
  `Estilo de abertura obrigatório: ${aberturaAtribuida}`,
  `Fecho obrigatório desta mensagem: "${fechoAtribuido}"`,
  '',
  'Escreve uma mensagem CURTA (1-2 frases), tão específica que só podia ser para esta pessoa. Devolve apenas o JSON pedido.',
].join('\n');

return { json: { clienteId: p.id, nome: p.nome, systemPrompt, userPrompt, diasSemSessao, servicoFrequente, fechoAtribuido, aberturaAtribuida } };

const prep = $('Preparar Prompt Reativação').item.json;
const raw = ($json.content && $json.content[0] && $json.content[0].text) || '';

let mensagem = '';
let motivo = 'Reativação — cliente inativa';
try {
  const clean = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const d = clean ? JSON.parse(clean) : {};
  mensagem = (d.mensagem || '').trim();
  motivo = (d.motivo || motivo).slice(0, 300);
} catch (e) {
  // conteúdo vazio ou JSON inválido
}

// Rede de segurança determinística — já vimos o modelo repetir sugestões de
// marcação mesmo depois de instruído a não o fazer. Não confiar só no prompt
// para esta regra — varrer o texto final também. Sem exigir "?" a seguir
// (a 1a versão só apanhava perguntas e deixou passar "a gente combina um
// tempo" que termina em ponto final).
const PADROES_PROIBIDOS = [
  /combin(a|amos|ar|ados?|ámos)\b/i,
  /acalmar/i,
  /vamos marcar/i,
  /a gente (quer|pode|vai) receb/i,
  /deixe-me confirmar/i,
  /queria perceber se conseguimos ajudar/i,
  /podemos ajudar (com|nisso)/i,
  /assim que puder,? (apareça|venha|volte)/i,
  /\bdela\b/i,
  /\bela mencionou\b/i,
];
const violacao = PADROES_PROIBIDOS.some(re => re.test(mensagem));

return { json: {
  clienteId: prep.clienteId,
  mensagemGerada: mensagem,
  motivoGeracao: motivo,
  falhou: !mensagem || violacao,
} };
